/**
 * Synthetic media fixtures: real, playable H.264/AAC streams generated by the
 * bundled FFmpeg.wasm (in Node), packaged the way servers deliver them:
 *
 * - MPEG-TS segments: video-only renditions, an audio-only rendition, and a
 *   muxed audio+video rendition (HLS);
 * - fragmented MP4: an init segment plus media fragments per rendition
 *   (HLS with EXT-X-MAP, DASH).
 *
 * The picture is FFmpeg's test pattern with a running frame counter and the
 * sound a beeping sine, so a merged file shows at a glance whether segments
 * are in order. A short clip is encoded once per rendition and repeated with
 * `-stream_loop` and stream copy, so long fixtures (the download demo's 8
 * minutes) take seconds to produce and keep continuous timestamps.
 *
 * Nothing is written to disk; results are cached per options within a process.
 * Plain relative imports only (scripts/fixture-server.ts runs this in Node).
 */
import type { FfmpegCore } from '../../../src/core/media/ffmpeg-core.ts';
import { createNodeCore } from './node-core.ts';

export interface VideoRenditionOptions {
  name: string;
  width: number;
  height: number;
}

export interface SyntheticOptions {
  /** Segment length in whole seconds (every segment starts with a keyframe). */
  segmentSeconds: number;
  /** Media segments per rendition (the last audio segment may be shorter). */
  segments: number;
  /** Length of the encoded clip that is repeated; must divide the total. Default: the total, at most 20 s. */
  clipSeconds?: number;
  fps?: number;
  /** x264 quality: lower is larger (default 36: tiny files). */
  crf?: number;
  /** Film-grain noise strength (0–100, default 0). The test pattern alone compresses to almost nothing; noise gives realistic bitrates for benchmarks. */
  noise?: number;
  video?: readonly VideoRenditionOptions[];
}

export interface Rendition {
  /** fMP4 initialisation segment. */
  init?: Uint8Array<ArrayBuffer>;
  segments: Uint8Array<ArrayBuffer>[];
  /** Seconds, per segment, as the packager wrote them in its playlist. */
  durations: number[];
}

export interface SyntheticMedia {
  options: Required<SyntheticOptions>;
  ts: { video: Record<string, Rendition>; audio: Rendition; muxed: Rendition };
  fmp4: { video: Record<string, Rendition>; audio: Rendition };
}

export const DEFAULT_VIDEO: readonly VideoRenditionOptions[] = [
  { name: 'v360', width: 640, height: 360 },
  { name: 'v180', width: 320, height: 180 },
];

/** Small and fast: what the unit and integration tests use. */
export const TEST_MEDIA: SyntheticOptions = {
  segmentSeconds: 2,
  segments: 4,
  fps: 10,
  video: [
    { name: 'v180', width: 320, height: 180 },
    { name: 'v90', width: 160, height: 90 },
  ],
};

const cache = new Map<string, Promise<SyntheticMedia>>();

export function syntheticMedia(options: SyntheticOptions = TEST_MEDIA): Promise<SyntheticMedia> {
  const resolved = resolveOptions(options);
  const key = JSON.stringify(resolved);
  let media = cache.get(key);
  if (!media) {
    media = generate(resolved);
    cache.set(key, media);
    media.catch(() => cache.delete(key));
  }
  return media;
}

function resolveOptions(options: SyntheticOptions): Required<SyntheticOptions> {
  const total = options.segments * options.segmentSeconds;
  const clip = options.clipSeconds ?? (total <= 20 ? total : (largestDivisor(total, 20, options.segmentSeconds) ?? total));
  if (!Number.isInteger(options.segmentSeconds) || options.segmentSeconds < 1) throw new Error('segmentSeconds must be a whole number');
  if (total % clip !== 0 || clip % options.segmentSeconds !== 0) throw new Error('clipSeconds must divide the total and be whole segments');
  return {
    segmentSeconds: options.segmentSeconds,
    segments: options.segments,
    clipSeconds: clip,
    fps: options.fps ?? 10,
    crf: options.crf ?? 36,
    noise: options.noise ?? 0,
    video: options.video ?? DEFAULT_VIDEO,
  };
}

/** The largest multiple of `step` ≤ `max` that divides `total`. */
function largestDivisor(total: number, max: number, step: number): number | undefined {
  for (let clip = Math.floor(max / step) * step; clip >= step; clip -= step) if (total % clip === 0) return clip;
  return undefined;
}

class Packager {
  readonly #core: FfmpegCore;
  #errors: string[] = [];

  constructor(core: FfmpegCore) {
    this.#core = core;
    core.setLogger(({ type, message }) => {
      if (type === 'stderr') this.#errors.push(message);
    });
  }

  run(...args: string[]): void {
    this.#errors = [];
    const code = this.#core.exec('-hide_banner', '-loglevel', 'error', ...args);
    this.#core.reset();
    if (code !== 0) throw new Error(`FFmpeg failed (${code}): ${args.join(' ')}\n${this.#errors.join('\n')}`);
  }

  mkdir(path: string): void {
    if (!this.#core.FS.analyzePath(path).exists) this.#core.FS.mkdir(path);
  }

  read(path: string): Uint8Array<ArrayBuffer> {
    const bytes = this.#core.FS.readFile(path);
    const copy = new Uint8Array(bytes.length);
    copy.set(bytes);
    return copy;
  }

  /** Reads an HLS packaging: playlist durations and segment files, plus the init segment if any. */
  rendition(dir: string): Rendition {
    const playlist = new TextDecoder().decode(this.read(`${dir}/index.m3u8`));
    const durations: number[] = [];
    const segments: Uint8Array<ArrayBuffer>[] = [];
    let duration: number | undefined;
    for (const line of playlist.split('\n').map((entry) => entry.trim())) {
      const extinf = /^#EXTINF:([\d.]+)/.exec(line);
      if (extinf) duration = Number(extinf[1]);
      else if (line !== '' && !line.startsWith('#') && duration !== undefined) {
        durations.push(duration);
        segments.push(this.read(`${dir}/${line}`));
        duration = undefined;
      }
    }
    const rendition: Rendition = { segments, durations };
    if (/#EXT-X-MAP/.test(playlist)) rendition.init = this.read(`${dir}/init.mp4`);
    return rendition;
  }
}

async function generate(options: Required<SyntheticOptions>): Promise<SyntheticMedia> {
  const core = await createNodeCore();
  const ffmpeg = new Packager(core);
  const { segmentSeconds, clipSeconds, fps } = options;
  const total = options.segments * segmentSeconds;
  const loops = String(total / clipSeconds - 1);
  const gop = String(segmentSeconds * fps);

  ffmpeg.mkdir('/clips');
  for (const video of options.video) {
    ffmpeg.run(
      ...['-f', 'lavfi', '-i', `testsrc=duration=${clipSeconds}:size=${video.width}x${video.height}:rate=${fps}`],
      ...(options.noise > 0 ? ['-vf', `noise=alls=${options.noise}:allf=t`] : []),
      ...['-c:v', 'libx264', '-preset', 'veryfast', '-crf', String(options.crf), '-pix_fmt', 'yuv420p', '-bf', '0'],
      ...['-g', gop, '-keyint_min', gop, '-sc_threshold', '0', `/clips/${video.name}.mkv`],
    );
  }
  ffmpeg.run(
    ...['-f', 'lavfi', '-i', `sine=frequency=440:beep_factor=4:duration=${clipSeconds}:sample_rate=48000`],
    ...['-ac', '2', '-c:a', 'aac', '-b:a', '48k', '/clips/audio.mkv'],
  );

  /** Repeats the clip(s) to the full length and cuts them into HLS segments, by stream copy. */
  const segment = (dir: string, inputs: string[], fmp4: boolean): Rendition => {
    ffmpeg.mkdir(dir);
    const args = inputs.flatMap((input) => ['-stream_loop', loops, '-i', `/clips/${input}.mkv`]);
    const maps = inputs.flatMap((_, index) => ['-map', String(index)]);
    const packaging = fmp4
      ? ['-hls_segment_type', 'fmp4', '-hls_fmp4_init_filename', 'init.mp4', '-hls_segment_filename', `${dir}/seg-%d.m4s`]
      : ['-hls_segment_filename', `${dir}/seg-%d.ts`];
    ffmpeg.run(...args, ...maps, '-c', 'copy', '-f', 'hls', '-hls_time', String(segmentSeconds), '-hls_playlist_type', 'vod', ...packaging, `${dir}/index.m3u8`);
    return ffmpeg.rendition(dir);
  };

  const media: SyntheticMedia = {
    options,
    ts: { video: {}, audio: segment('/ts-audio', ['audio'], false), muxed: segment('/ts-muxed', [options.video[0]?.name ?? '', 'audio'], false) },
    fmp4: { video: {}, audio: segment('/fmp4-audio', ['audio'], true) },
  };
  for (const video of options.video) {
    media.ts.video[video.name] = segment(`/ts-${video.name}`, [video.name], false);
    media.fmp4.video[video.name] = segment(`/fmp4-${video.name}`, [video.name], true);
  }
  return media;
}
